import asyncio
from fastapi import FastAPI, Form, File, UploadFile
from fastapi.testclient import TestClient
from starlette.datastructures import FormData

app = FastAPI()

@app.post("/upload")
async def upload(
    form_data: str = Form(...),
    file1: bytes = File(...),
    file2: bytes = File(...),
):
    return {"form_data": form_data, "file1": file1, "file2": file2}

@app.post("/upload_files")
async def upload_files(
    files: list[bytes] = File(...),
    form_data: str = Form(...),
):
    return {"form_data": form_data, "files": files}

client = TestClient(app)

def test_mixed_order():
    print("Testing mixed order: Form, File, File")
    response = client.post(
        "/upload",
        data={"form_data": "hello", "file1": b"content1", "file2": b"content2"},
    )
    print(f"Response: {response.status_code}, Body: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "file1": b"content1", "file2": b"content2"}

def test_files_first():
    print("Testing files first: List[bytes], Form")
    response = client.post(
        "/upload_files",
        data={"files": [b"content1", b"content2"], "form_data": "hello"},
    )
    print(f"Response: {response.status_code}, Body: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "files": [b"content1", b"content2"]}

def test_form_first_list():
    print("Testing form first, then list of files")
    @app.post("/upload_list")
    async def upload_list(form_data: str = Form(...), files: list[bytes] = File(...)):
        return {"form_data": form_data, "files": files}

    response = client.post(
        "/upload_list",
        data={"form_data": "hello", "files": [b"content1", b"content2"]},
    )
    print(f"Response: {response.status_code}, Body: {response.json()}")
    assert response.status_code == 200
    assert response.json() == {"form_data": "hello", "files": [b"content1", b"content2"]}

if __name__ == "__main__":
    try:
        test_mixed_order()
        test_files_first()
        test_form_first_list()
        print("All tests passed!")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()
        exit(1)

